using System.Configuration;


// Generated by AI. Edited.
namespace Tune.Local.DAO
{
    /// <summary>
    /// 设置工具类（支持 TuneSettings 和 App.config）
    /// </summary>
    public static class LocalProperties
    {
        #region ========== 1. TuneSettings 封装 ==========

        /// <summary>
        /// 读取用户/应用程序设置（强类型）
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        /// <param name="key">设置项名称</param>
        /// <param name="defaultValue">如果键不存在则返回的默认值</param>
        /// <returns>设置值</returns>
        public static T? GetUserSetting<T>(string key, T? defaultValue = default)
        {
            try
            {
                object value = TuneSettings.Default[key];
                if (value == null || value == DBNull.Value)
                    return defaultValue;

                return (T)Convert.ChangeType(value, typeof(T));
            }
            catch
            {
                return defaultValue;
            }
        }

        /// <summary>
        /// 写入用户设置（仅限 User 作用域），并自动保存
        /// </summary>
        /// <typeparam name="T">类型</typeparam>
        /// <param name="key">设置项名称</param>
        /// <param name="value">要写入的值</param>
        public static void SetUserSetting<T>(string key, T value)
        {
            try
            {
                TuneSettings.Default[key] = value;
                TuneSettings.Default.Save();
            }
            catch (Exception ex)
            {
                // 可根据需要记录日志或抛出
                throw new InvalidOperationException($"Failed to save setting '{key}': {ex.Message}", ex);
            }
        }

        /// <summary>
        /// 重置所有用户设置为默认值
        /// </summary>
        public static void ResetUserSettings()
        {
            TuneSettings.Default.Reset();
            TuneSettings.Default.Save();
        }

        /// <summary>
        /// 立即保存所有用户设置（通常在程序退出时调用）
        /// </summary>
        public static void SaveUserSettings()
        {
            TuneSettings.Default.Save();
        }

        #endregion

        #region ========== 2. App.config (appSettings) 封装 ==========

        /// <summary>
        /// 从 App.config 的 appSettings 中读取字符串值
        /// </summary>
        /// <param name="key">键</param>
        /// <param name="defaultValue">默认值</param>
        /// <returns>配置值</returns>
        public static string? GetAppConfig(string key, string? defaultValue = "")
        {
            try
            {
                var value = ConfigurationManager.AppSettings[key];
                return string.IsNullOrEmpty(value) ? defaultValue : value;
            }
            catch
            {
                return defaultValue;
            }
        }

        /// <summary>
        /// 从 App.config 读取并转换为指定类型
        /// </summary>
        /// <typeparam name="T">目标类型（需支持 Convert.ChangeType）</typeparam>
        public static T? GetAppConfig<T>(string key, T? defaultValue = default)
        {
            string? raw = GetAppConfig(key, null);
            if (string.IsNullOrEmpty(raw))
                return defaultValue;

            try
            {
                return (T)Convert.ChangeType(raw, typeof(T));
            }
            catch
            {
                return defaultValue;
            }
        }

        /// <summary>
        /// 刷新 App.config 缓存（运行时修改后使用）
        /// </summary>
        public static void RefreshAppConfig()
        {
            ConfigurationManager.RefreshSection("appSettings");
        }

        #endregion

        #region ========== 3. 综合便捷方法（自动选择来源） ==========

        /// <summary>
        /// 优先从 User Settings 读取，若不存在则从 App.config 读取
        /// </summary>
        public static T? GetSetting<T>(string key, T? defaultValue = default)
        {
            // 先尝试从 TuneSettings 读取
            try
            {
                object val = TuneSettings.Default[key];
                if (val != null && val != DBNull.Value)
                    return (T)Convert.ChangeType(val, typeof(T));
            }
            catch { /* 忽略 */ }

            // 再尝试从 App.config 读取
            return GetAppConfig<T>(key, defaultValue);
        }

        #endregion
    }
}
